query.base:
TS metrics-gcp.cloudsql_sqlserver.otel-*
| WHERE gcp.resource_type == "cloudsql_database"
// Only the documents the rule needs: uptime, the engine marker and stopped states.
| WHERE `cloudsql.googleapis.com/database/uptime` IS NOT NULL
     OR `cloudsql.googleapis.com/database/sqlserver/memory/page_life_expectancy` IS NOT NULL
     OR (`cloudsql.googleapis.com/database/instance_state` == 1 AND attributes.state == "RUNNABLE")
// uptime is a DELTA metric: seconds the instance ran within each 60 s sample. Running
// minutes read 59-61 s. MIN per minute, so a duplicated or jittered sample cannot hide
// a partial minute. Only stopped instance_state samples pass the filter above, so their
// count marks stopped minutes.
| STATS uptime_s = MIN(MIN_OVER_TIME(`cloudsql.googleapis.com/database/uptime`)),
        ss = SUM(COUNT_OVER_TIME(`cloudsql.googleapis.com/database/sqlserver/memory/page_life_expectancy`)),
        stopped = SUM(COUNT_OVER_TIME(`cloudsql.googleapis.com/database/instance_state`))
    BY minute = TBUCKET(1 minute), database_id
// The SQL Server engine marker covers the whole 1-hour rule window, so the minutes around
// a restart stay in scope. Candidates: partial minutes (0 < uptime < 58 s, one second
// below the healthy 59-61 s jitter) in the last 30 minutes (>= 15 min for ingestion delay).
| INLINE STATS ss_total = SUM(ss),
               candidate = VALUES(minute) WHERE uptime_s > 0 AND uptime_s < 58 AND minute >= NOW() - 30 minutes
    BY database_id
| WHERE ss_total > 0 AND candidate IS NOT NULL
// Compare every candidate with every minute of its instance: the nearest full minutes
// around it, the next short minute after it and the nearest stopped (RUNNABLE) minutes.
| MV_EXPAND candidate
| STATS next_full = MIN(minute) WHERE minute > candidate AND uptime_s >= 58,
        prev_full = MAX(minute) WHERE minute < candidate AND uptime_s >= 58,
        next_short = MIN(minute) WHERE minute > candidate AND uptime_s < 58,
        stop_before = MAX(minute) WHERE minute < candidate AND stopped > 0,
        stop_after = MIN(minute) WHERE minute >= candidate AND stopped > 0
    BY database_id, candidate
// A start is the last short minute before a full minute. The partial minute before an
// outage is followed by another short minute (or none yet), so a restart counts once.
| WHERE next_full IS NOT NULL AND (next_short IS NULL OR next_short > next_full)
// Owner stop and start: skip a start with a stopped (RUNNABLE) minute between it and the
// neighbouring full minutes. The instance down rule covers those stops. Remove this
// filter to alert on owner starts too.
| WHERE (stop_before IS NULL OR stop_before < prev_full)
    AND (stop_after IS NULL OR stop_after > next_full)
| STATS restarts = COUNT(*), last_restart = MAX(candidate) BY database_id
